package com.JavaClass;

public class PostDecrement {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 10;
		System.out.println(--a); //9
		System.out.println(a--); //9 
		System.out.println(--a); //?
		System.out.println(a);
		System.out.println(a--);
		System.out.println(a);


	}

}
